    report=S.HERE/'REPORT.md';old=report.read_text();assert '### H2bs:' not in old
    a=json.loads((D/'audit.json').read_text());v=json.loads((D/'public-verification.json').read_text());p=json.loads((D/'protocol.json').read_text());m=json.loads((D/'evidence-manifest.json').read_text());sa=json.loads((D/'source-context/audit.json').read_text());endpoint=a['cost_endpoint'];pct=100*endpoint['median_saving'];prefix='../../../results/research/work/bp-first-packed-dispatch/'
